import React from 'react';

import { mapFrontInterviewToBack } from '@apps/Interview/@mappers/interview.mapper';
import { addInterview, updateInterview } from '@apps/Interview/@services/interview.service';
import { IInterview } from '@apps/Interview/@types/interview.types';
import { selectHikingAsync } from '@components/HikingSelector';
import { getInputDate } from '@helpers/dateHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

interface IEditInterviewProps {
  data: IInterview;
  onSave: (data: IInterview) => void;
}

const EditInterview: React.FC<IEditInterviewProps> = ({ data, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);

  const [error, setError] = React.useState<Error>();
  const [addData, setAddData] = React.useState<IInterview>(data);

  const handleInputChange =
    <T extends IInterview, K extends keyof T>(field: keyof T) =>
    (value: T[K]) => {
      setAddData((fd) => ({
        ...(fd as T),
        [field]: value,
      }));
    };

  return (
    <form
      style={{ minWidth: 420, width: '80vw' }}
      onSubmit={async (e) => {
        e.preventDefault();
        try {
          setIsLoading(true);
          const up = { ...addData };
          if (!addData.id) {
            const id = await addInterview(mapFrontInterviewToBack(addData));
            up.id = id;
          } else {
            await updateInterview(mapFrontInterviewToBack(addData));
          }

          onSave(up);
        } catch (er) {
          setError(er as Error);
        } finally {
          setIsLoading(false);
        }
      }}
    >
      <PohInput
        horizontal
        required
        label="Название"
        value={addData.name}
        onChange={handleInputChange('name')}
        placeholder="Название"
        disabled={isLoading}
      />
      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={5}>
          <PohInput
            required
            label="Действует с"
            value={addData.date_start ? getInputDate(addData.date_start, true) : ''}
            onChange={(v) => handleInputChange('date_start')(new Date(v))}
            disabled={isLoading}
            type={InputTypes.date}
          />
        </PohCol>
        <PohCol sm={5}>
          <PohInput
            required
            label="Действует по"
            value={addData.date_finish ? getInputDate(addData.date_finish, true) : ''}
            onChange={(v) => handleInputChange('date_finish')(new Date(v))}
            disabled={isLoading}
            type={InputTypes.date}
          />
        </PohCol>
      </PohRow>

      <PohInput
        horizontal
        label="Поход"
        value={addData.hiking?.name ?? ''}
        onClick={async (e) => {
          const el = e.target as HTMLInputElement;
          if (el.value.length > 0) return;
          const selected = await selectHikingAsync();
          handleInputChange('hiking')(selected);
        }}
        onInput={(e) => {
          const el = e.target as HTMLInputElement;

          if (el.value === '') {
            e.stopPropagation();
            e.preventDefault();
            handleInputChange('hiking')(null);
            handleInputChange('isMain')(false);
            el.blur();
          }
        }}
        placeholder="Выберите поход (если опрос для похода)"
        disabled={isLoading}
        type={InputTypes.search}
      />

      {addData.hiking && (
        <>
          <PohRow className="mb-3">
            <PohCol sm={2} />
            <PohCol sm={10}>
              <PohCheckbox
                label="Основной опрос для похода"
                onChange={handleInputChange('isMain')}
                checked={addData.isMain}
              />
            </PohCol>
          </PohRow>
        </>
      )}

      <PohInput
        horizontal
        required
        label="Ограничение"
        value={addData.members_limit > 0 ? addData.members_limit.toString() : ''}
        onChange={handleInputChange('members_limit')}
        disabled={isLoading}
        type={InputTypes.number}
      />

      <PohInput
        horizontal
        required
        label="Описание"
        value={addData.description}
        onChange={handleInputChange('description')}
        placeholder="Описание"
        disabled={isLoading}
        type={InputTypes.textarea}
      />

      <PohInput
        horizontal
        required
        label="Приветствие"
        value={addData.hello_text}
        onChange={handleInputChange('hello_text')}
        placeholder="Приветствие"
        disabled={isLoading}
        type={InputTypes.textarea}
      />
      <PohInput
        horizontal
        required
        label="Прощание"
        value={addData.by_text}
        onChange={handleInputChange('by_text')}
        placeholder="Прощание"
        disabled={isLoading}
        type={InputTypes.textarea}
      />

      <footer className="text-end pt-2 mb-n3">
        {error && <PohAlert variant={AlertVariant.Danger}>{error.message}</PohAlert>}
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </form>
  );
};

export const editInterview = (data: IInterview): Promise<IInterview> => {
  return new Promise((res) => {
    showModal({
      title: data.id && +data.id > 0 ? 'Редактирование опроса' : 'Добавление опроса',
      children: (clos) => (
        <EditInterview
          data={data}
          onSave={(r) => {
            res(r);
            clos();
          }}
        />
      ),
    });
  });
};
