import React from 'react';

import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import { getHikingListForUserOrFriend } from '@apps/Hiking/@services/hikingList.service';
import { IBaseHiking } from '@apps/Hiking/@types/hikingList.types';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

interface IHikingSelectorProps {
  onSelect: (selected: IBaseHiking) => void;
}

const HikingSelector: React.FC<IHikingSelectorProps> = ({ onSelect }) => {
  const [hikingList, setHikingList] = React.useState<IBaseHiking[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const typesData = await getHikingListForUserOrFriend();
        setHikingList(typesData);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, []);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      <PohList
        data={hikingList.map((hiking) => ({
          key: hiking.id,
          content: <HikingBadge hiking={hiking} />,
          action: true,
          onClick: () => onSelect(hiking),
        }))}
      />
    </div>
  );
};

export function selectHikingAsync(): Promise<IBaseHiking> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: 'Выбор похода',
      children: (closeHandler: () => void) => (
        <HikingSelector
          onSelect={(s) => {
            resolve(s);
            closeHandler();
          }}
        />
      ),
    });
  });
}
